import{_ as n,o as i,c as t,ae as r}from"./chunks/framework.BvHJbMD4.js";const m=JSON.parse('{"title":"DAS HORTEN-MYSTERIUM","description":"","frontmatter":{"layout":"home","hero":{"name":"Dokfilm","text":"Hinter den Kulissen einer Mockumentary","tagline":"Die Entstehung dokumentiert mit Gemini CLI","actions":[{"theme":"brand","text":"Zum Logbuch","link":"/logbuch/"},{"theme":"alt","text":"Das Konzept","link":"/konzept"}]},"features":[{"title":"Authentisch","details":"Ein ehrlicher Blick auf die Hürden und Erfolge der Filmproduktion."},{"title":"KI-gestützt","details":"Dokumentiert und aufbereitet mit Hilfe von Gemini CLI."},{"title":"Open Process","details":"Alles ist für die Öffentlichkeit transparent einsehbar."}]},"headers":[],"relativePath":"index.md","filePath":"index.md"}'),s={name:"index.md"};function a(d,e,h,o,u,c){return i(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="das-horten-mysterium" tabindex="-1">DAS HORTEN-MYSTERIUM <a class="header-anchor" href="#das-horten-mysterium" aria-label="Permalink to &quot;DAS HORTEN-MYSTERIUM&quot;">​</a></h1><p><strong>Eine fabelhafte Fiktion von Macht, Geld und Perlen – Wo die Wahrheit ein Gerücht ist und die Gerüchte die Wahrheit werden!</strong></p><p>Vergessen Sie, was Sie zu wissen glauben! Tauchen Sie ein in eine Welt, in der die Grenzen zwischen Legende und Lügen verschwimmen: <em>Das Horten-Mysterium</em> ist die explosivste Mockumentary des Jahres, die das Leben der Jetset-Königin Heidi Goëss-Horten und ihres sagenumwobenen Gatten Helmut auf links dreht!</p><p>Erleben Sie, wie Helmut Horten, der „Schnäppchenjäger des 20. Jahrhunderts“, in den dunkelsten Stunden der Geschichte sein Imperium „erwirtschaftete“ – eine schonungslos-satirische Reise durch eine Zeit, in der „Arisierung“ nur ein anderes Wort für „geschicktes Investment“ war. Werden Sie Zeuge, wie die tragische Geschichte der Gebrüder Alsberg zur bizarr-komischen Farce eines bürokratischen Totalversagens wird!</p><p>Doch das ist nur der Anfang! Folgen Sie der schillernden Witwe Heidi Horten, wie sie ihr Leben nach Helmuts Tod in einen schwindelerregenden Strudel aus unermesslichem Reichtum, exquisitem Geschmack und – natürlich – einem schier endlosen Fluss von Spenden an die österreichische Volkspartei verwandelt. Sehen Sie, wie Politiker in aberwitzigen Verrenkungen versuchen, die magische „Spendenstückelung“ zu erklären, während der Rechnungshof verzweifelt nach einem roten Faden sucht – und nur ein Gewirr aus „kleinen Aufmerksamkeiten“ findet!</p><p><em>Das Horten-Mysterium</em> ist ein gewagter Blick hinter die Samtvorhänge der Macht und des Geldes, eine provokante Mischung aus Satire und Fiktion, die Sie zum Lachen, Kopfschütteln und vor allem zum Nachdenken bringen wird. Kommen Sie und erleben Sie die Geschichte, wie sie <em>hätte</em> sein können – oder vielleicht doch war?</p>',6)])])}const g=n(s,[["render",a]]);export{m as __pageData,g as default};
